// MESA CLUB 8.0 · 6 juegos 1v1: futbolito, ping pong, air hockey, ajedrez, domino y billar.
'use strict';
const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');const zlib=require('node:zlib');
const payload='';
const bytes=Buffer.from(payload,'base64');
if(crypto.createHash('sha256').update(bytes).digest('hex')!=='316e252bd43d837912c1c77f53776f2ce00843268dcfb1a1a460f6053e157431')throw Error('Integridad de MESA CLUB 8 inválida');
const contents=JSON.parse(zlib.brotliDecompressSync(bytes).toString('utf8'));
for(const [name,code] of Object.entries(contents)){
 if(!/^(server|chess|store|domino|pool|arcade|backup|migrate)\.js$|^public\/(index\.html|app\.js|styles\.css)$/.test(name))throw Error('Ruta de paquete inválida');
 const target=path.join(__dirname,name);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,code);
}
console.log('MESA CLUB 8 preparado: Futbolito 1v1, Ping Pong y Air Hockey online.');
const {server}=require('./server');
const {init,getStorage,shutdown}=require('./store');
init().then(()=>server.listen(Number(process.env.PORT)||3000,'0.0.0.0',()=>console.log('MESA CLUB 8 online · almacenamiento: '+getStorage()))).catch(err=>{console.error('No se pudo conectar a la base de datos:',err.message);process.exitCode=1;shutdown().catch(()=>{});server.close();});
